#!/bin/bash
#SBATCH --job-name=fb3d_xsfix
#SBATCH --partition=gpu-xe9680q
#SBATCH --gres=gpu:1
#SBATCH --time=08:00:00
#SBATCH --ntasks=1
#SBATCH --cpus-per-task=8
#SBATCH --mem=64G
#SBATCH --array=1-48%8
#SBATCH --output=logs/xsite/xsfix_%A_%a.out
#SBATCH --error=logs/xsite/xsfix_%A_%a.err

# Cross-site LOSO retrained with early stopping disabled, BOTH label collapses.
# thread facebase3d-xsitediag-2026-09-07.
# Rationale and evidence: the cross-site block in facebench/eval/rerun_config.py.
# Joblist is GENERATED by make_xsite_fix_jobs.py — do not hand-edit it.
#
# PARTITION NOTE. The published cross-site arm trained on gpuq with an explicit
# --gres=gpu:a100:1 so all 24 runs shared one device class. These 48 run on
# gpu-xe9680q, which is where the A1_fix/A2_fix sweeps ran and where capacity is.
# Device class is homogeneous WITHIN this sweep, which is what the comparisons
# inside it require; CPU-side scoring is unaffected because extraction runs on
# CPU from the checkpoints either way.
set -euo pipefail

JOBLIST="${FACEBENCH_ROOT:?set FACEBENCH_ROOT to the repository root}"/facebench/eval/xsite_fix_joblist.txt
N=$(grep -c . "$JOBLIST")
if [ "$N" -ne 48 ]; then
  echo "joblist has $N lines, expected 48 — refusing" >&2; exit 1
fi
CMD=$(sed -n "${SLURM_ARRAY_TASK_ID}p" "$JOBLIST")

mkdir -p logs/xsite

echo "cross-site fix array — task ${SLURM_ARRAY_TASK_ID}/48"
echo "Node: $(hostname)  GPU: ${CUDA_VISIBLE_DEVICES:-none}"
echo "CMD: $CMD"
date
eval "$CMD"
echo "Done at $(date)"
